    reliefNote = `65\uC138 \uC774\uC0C1 1\uC8FC\uD0DD\uC790 \uBE44\uC218\uB3C4\uAD8C \uC774\uC8FC \u2014 ${(sr.rate * 100).toFixed(0)}% \uAC10\uBA74(\uD55C\uB3C4 ${rfEok(sr.cap)})`;
    tax -= relief;
