    const val = answers[q.id];
    if (val === void 0 || val === null || val === "") return;
    let v = val;
    if (q.opts) {
      const o = q.opts.find((x) => x[0] === val);
      if (o) v = o[1];
    } else if (q.numeric && q.money) v = formatWon(Number(val));
    const ql = (q.q || q.id).replace(/\s*\([^)]*\)\s*$/, "").trim();
    L.push("  \xB7 " + ql + ": " + v);
